#[test]fn full_conversion_reserves_entire_budget_and_excludes_readers_both_directions() {
 let budget=Budget::new(AdmissionLimits::default()).unwrap();let reader=budget.reserve(Operation::Reader).unwrap();assert!(budget.reserve(Operation::Conversion).is_err());drop(reader);let c=budget.reserve(Operation::Conversion).unwrap();assert_eq!(budget.snapshot().reserved_memory_bytes,384*1024*1024);assert_eq!(budget.snapshot().reserved_temporary_bytes,768*1024*1024);assert!(budget.reserve(Operation::Reader).is_err());assert!(budget.reserve(Operation::Packing).is_err());drop(c);assert_eq!(budget.snapshot().active_operations,0);
 let f=Fixture::new();let runtime=Runtime::new(AdmissionLimits::default(),runner::Config::default()).unwrap();let reader=ready(&runtime,&f);let id=runtime.publication().submit(f.conversion("blocked.txt")).unwrap();let s=wait(runtime.publication(),&id);assert_eq!(s.state,JobState::Failed);assert_eq!(s.error.unwrap().detail,"resource_admission");assert!(!f.conversion("blocked.txt").destination().unwrap().exists());runtime.publication().forget(&id).unwrap();reader.join().unwrap();let id=runtime.publication().submit(f.conversion("converted.txt")).unwrap();assert_eq!(wait(runtime.publication(),&id).state,JobState::Succeeded);assert!(matches!(runtime.publication().take_result(&id).unwrap(),Some(Response::Conversion(converters::Receipt::Cc(r))) if r.entries==4096&&r.comments_count==1));assert_eq!(runtime.admission().active_operations,0);runtime.join().unwrap();
}
#[test]fn conversion_cancel_before_commit_and_late_cancel_after_commit() {
 for committed in [false,true] {let f=Fixture::new();let gate=Gate::new();let _release=Release(gate.clone());let g=gate.clone();let budget=Budget::new(AdmissionLimits::default()).unwrap();let runner=runner::Runner::with_executor(runner::Config::default(),budget.clone(),Arc::new(move|request,job| {if committed {let result=execute(request,job)?;g.hit();Ok(result)}else {let mut cb=|p:Progress| {if p.phase=="converting"&&p.completed>=256 {g.hit();}};execute(request,&mut ImportJob::new(job.id,job.token,&mut cb))}})).unwrap();let id=runner.submit(f.conversion("cancel.txt")).unwrap();gate.entered();assert_eq!(budget.snapshot().conversions,1);if !committed {let queued=runner.submit(f.pack("queued-during-convert.mdx")).unwrap();runner.cancel(&queued).unwrap();assert_eq!(wait(&runner,&queued).state,JobState::Cancelled);}runner.cancel(&id).unwrap();runner.shutdown();gate.release();assert_eq!(wait(&runner,&id).state,if committed {JobState::Succeeded}else{JobState::Cancelled});assert_eq!(f.conversion("cancel.txt").destination().unwrap().exists(),committed);assert_eq!(budget.snapshot().active_operations,0);runner.join().unwrap();}
}
