 let id=runtime.publication().submit(limited).unwrap();assert_eq!(wait(runtime.publication(),&id).error.unwrap().code,ErrorCode::LimitExceeded);assert!(!f.dir.path().join("limited.txt").exists());runtime.publication().forget(&id).unwrap();let id=runtime.publication().submit(f.grouped("recover.txt","moe_revised")).unwrap();assert_eq!(wait(runtime.publication(),&id).state,JobState::Succeeded);runtime.join().unwrap();
