#[test]fn index_admission_refuses_reader_overlap_and_retries_with_verified_cache() {
 let f=Fixture::new();let runtime=Runtime::new(AdmissionLimits::default(),runner::Config::default()).unwrap();let reader=ready(&runtime,&f);let id=runtime.publication().submit(f.build_index("cache.idx")).unwrap();let s=wait(runtime.publication(),&id);assert_eq!(s.state,JobState::Failed);assert_eq!(s.error.unwrap().detail,"resource_admission");assert!(!f.dir.path().join("cache.idx").exists());runtime.publication().forget(&id).unwrap();reader.join().unwrap();
 let id=runtime.publication().submit(f.build_index("cache.idx")).unwrap();assert_eq!(wait(runtime.publication(),&id).state,JobState::Succeeded);let result=runtime.publication().take_result(&id).unwrap().unwrap();assert!(matches!(&result,Response::Index(r) if r.manifest.records==4096&&r.bytes>4096));assert!(serde_json::to_vec(&result).unwrap().len()<4096);assert!(runtime.publication().take_result(&id).unwrap().is_none());assert_eq!(runtime.admission().index_builds,0);
 let token=CancellationToken::default();let mut cb=|_|{};let mut job=studio_indexed_engine::ImportJob::new("reopen",&token,&mut cb);let d=studio_indexed_engine::Dictionary::open_v2(&f.dir.path().join("index-source.mdx"),studio_indexed_engine::Kind::Mdx,&studio_indexed_engine::Limits::default(),&mut job).unwrap();let idx=studio_indexed_engine::index::Index::open(&d,&f.dir.path().join("cache.idx"),studio_indexed_engine::index::Policy::RawExact,&mut job).unwrap();assert_eq!(idx.manifest().records,4096);runtime.join().unwrap();
}
